// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'TU-USUARIO/meridiano-motor',                    // repositorio donde corre el motor (GitHub Actions)
  github_rama: 'main',
  supabase_url: 'https://xxxxxxxx.supabase.co',
  hoja_datos_id: 'ID-de-la-hoja-de-Google-Sheets',               // lo que va entre /d/ y /edit en la URL de la hoja
  panel_url: 'https://meridiano-panel.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',                           // responsable de la hoja de datos (avisos de la carga)
  modelo_ia: 'claude-sonnet-5-5',
  // MODO DEMO (datos ficticios): todos los correos van al buzón de pruebas, con el destinatario real en el asunto.
  // Los correos salen de la cuenta de Gmail conectada en n8n; el buzón de pruebas puede ser esa misma cuenta (con alias +demo).
  modo_demo: true,
  buzon_demo: 'TU-CUENTA+demo@gmail.com',
} }];

// Ciclo semanal (martes por la mañana): la fecha de corte es el lunes anterior, con los datos de la semana ya cerrados.
// Para una ejecución manual de prueba, cambiar por: return [{ json: { fecha_corte: '2026-09-28' } }];
const hoy = new Date();
const dia = hoy.getUTCDay();                               // 0 domingo … 2 martes
const atras = ((dia - 1) + 7) % 7 || 7;                    // días hasta el lunes anterior (un lunes, el de la semana pasada)
const lunes = new Date(Date.UTC(hoy.getUTCFullYear(), hoy.getUTCMonth(), hoy.getUTCDate() - atras));
return [{ json: { fecha_corte: lunes.toISOString().slice(0, 10) } }];

// Lo que devuelve la acción de GitHub al terminar (o nada, si el tiempo de espera se agotó).
const b = ($input.first().json || {}).body;
if (!b || typeof b !== 'object') {
  return [{ json: { ok: false, error: 'El motor no ha respondido en 30 minutos (revisa la pestaña Actions del repositorio)' } }];
}
return [{ json: b }];

// Solo si el motor falló o no respondió: aviso a dirección (no se publica ningún plan nuevo).
return $input.all().filter(i => !i.json.ok).map(i => ({ json: {
  error: i.json.error || (i.json.body && i.json.body.message) || 'No se ha podido lanzar el motor en GitHub',
  ejecucion_github: i.json.ejecucion_github || '',
} }));

// Una propuesta por item para que la IA redacte cada material por separado (solo si el motor terminó bien).
const r = $input.first().json || {};
if (!r.ok) return [];
const lista = r.detalle_propuestas || [];
return lista.map(p => ({ json: { ...p, fecha_corte: p.fecha_corte || r.fecha_corte, etiqueta_vigente: r.etiqueta_vigente } }));

// Sensor computacional de Govern (equivalente a propuestas.validar_llm, con dos reglas más):
//  1. toda cifra del borrador debe aparecer en el contexto enviado a la IA;
//  2. ninguna condición económica (porcentajes, descuento, rebaja, gratis);
//  3. no menciona el riesgo de abandono;   4. máximo 200 palabras.
// Si falla cualquier regla o la IA no responde, se conserva la plantilla del motor y se anota el motivo.
const propuestas = $('Separar propuestas').all();
const numeros = s => new Set(String(s || '').match(/\d+(?:[.,]\d+)?/g) || []);
return $input.all().map((it, i) => {
  const p = propuestas[i].json;
  const r = it.json || {};
  const texto = Array.isArray(r.content)
    ? r.content.filter(c => c.type === 'text').map(c => c.text).join('\n').trim() : '';
  const motivos = [];
  if (!texto) motivos.push('IA no disponible' + (r.error ? ` (${String(r.error.message || r.error).slice(0, 80)})` : ''));
  else {
    const ctx = numeros(p.contexto_ia);
    const inventadas = [...numeros(texto)].filter(n => !ctx.has(n)).sort();
    if (inventadas.length) motivos.push(`cifras no trazables [${inventadas.join(', ')}]`);
    if (/\d+\s*%|descuento|rebaja|gratis/i.test(texto)) motivos.push('condición económica');
    if (/riesgo|abandon/i.test(texto)) motivos.push('menciona el riesgo');
    const palabras = texto.split(/\s+/).filter(Boolean).length;
    if (palabras > 200) motivos.push(`${palabras} palabras`);
  }
  const ok = motivos.length === 0;
  return { json: {
    fecha_corte: p.fecha_corte, id_cliente: p.id_cliente, razon_social: p.razon_social,
    comercial_asignado: p.comercial_asignado, comercial_nombre: p.comercial_nombre, correo_comercial: p.correo_comercial,
    material_cuerpo: ok ? texto : p.material_cuerpo,
    fuente_material: ok ? 'llm' : `plantilla (IA descartada: ${motivos.join('; ')})`,
    valido: ok,
  } };
});

// Un correo por comercial cada martes: sus propuestas nuevas de la semana. El detalle está en el panel.
const filas = $('Validador (sensor Govern)').all().map(i => i.json);
const panel = $('Configuración').first().json.panel_url;
const grupos = {};
for (const f of filas) (grupos[f.comercial_asignado] ??= []).push(f);
return Object.values(grupos).map(g => {
  const c = g[0];
  const lineas = g.map((f, i) => `${i + 1}. ${f.razon_social}`).join('\n');
  return { json: {
    correo: c.correo_comercial, comercial: c.comercial_nombre, propuestas: g.length,
    asunto: `Meridiano · ${g.length} cuentas nuevas en tu plan de retención (semana del ${c.fecha_corte})`,
    texto: `Hola, ${String(c.comercial_nombre || '').split(' ')[0]}:\n\n` +
      `Esta semana se añaden ${g.length} cuentas a tu plan, por orden de prioridad:\n\n${lineas}\n\n` +
      `En el panel tienes la ficha de cada cuenta, el motivo detectado y un material de apoyo que puedes editar antes de usarlo. ` +
      `Al terminar cada acción, ciérrala con el estado del cliente, el motivo y si el diagnóstico era correcto.\n\n${panel}\n\n` +
      `Este correo es interno. No se ha enviado nada a ningún anunciante.`,
  } };
});

// Registro de la ejecución de n8n en la tabla ejecuciones (trazabilidad para Govern).
const filas = $input.all().map(i => i.json);
const llm = filas.filter(f => f.valido).length;
return [{ json: { origen: 'n8n', estado: 'ok', detalle: {
  flujo: 'W1', fecha_corte: filas[0]?.fecha_corte, propuestas: filas.length,
  material_ia: llm, material_plantilla: filas.length - llm,
  descartes: filas.filter(f => !f.valido).map(f => ({ id_cliente: f.id_cliente, motivo: f.fuente_material })),
} } }];

